// Fetches full tour detail objects for a set of tour ids, in the same shape the
// category page feeds to <ListingCard> (media gallery, defaults, routes, rating,
// reviews_count, …). Used by the wishlist page so saved tours render with the
// standard tour card instead of a stripped-down one built from localStorage.
import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

export default async function getWishlistTours(tourIds: (number | string)[]) {
    if (!tourIds.length) return { tours: [], total: 0 };

    const res = await fetch(
        `${apiv2Base()}/b2c/tours/search`,
        {
            // Personalised list — never serve a stale/shared cache entry.
            cache: "no-store",
            method: "POST",
            headers: {
                ...apiv2ServerHeaders(),
                "Content-type": "application/json",
                "Content-Language": "en",
                "Accept": "*/*",
                "Accept-Encoding": "gzip, deflate, br",
                "Origin": "https://travelshopbooking.com",
            },
            body: JSON.stringify({
                ids: tourIds,
                page: 1,
                // Ask for as many as we have ids so none get paged out.
                page_size: tourIds.length,
            }),
        }
    );

    if (!res.ok) throw new Error("Failed to fetch wishlist tours");

    return res.json();
}
