"use client";
import { useEffect, useMemo, useState } from "react";
import { getCookie } from "cookies-next";
import { useWishlist } from "./wishlist-context";
import ListingCard from "@/components/tour/card/listing-card";
import ListingCardSkeleton from "@/components/tour/card/listing-card-skeleton";
import getWishlistTours from "@/services/wishlistToursService";
import getTourPricing from "@/services/tourPricingService";

export default function WishlistPage() {
  const { items, count, hydrated } = useWishlist();

  // Pool of full tour-detail objects (media gallery, defaults, routes, rating,
  // …) we've fetched — keyed lookups below pick from here. Same shape the
  // category page feeds to <ListingCard>.
  const [pool, setPool] = useState<Record<string, any>>({});
  // Only true on the very first load (empty pool) — un-hearting a card then
  // mutates the list locally without flashing the whole grid back to skeleton.
  const [toursLoading, setToursLoading] = useState(true);
  const [priceLoading, setPriceLoading] = useState(true);
  const [prices, setPrices] = useState<any[]>([]);

  // The list of saved ids, joined to a primitive so effects re-run only when the
  // actual set changes (not on every render / unrelated context update).
  const idsKey = items.map((i) => i.id).join(",");

  // Displayed tours: saved order (most-recently-added first), resolved against
  // the fetched pool. Removed-from-wishlist tours drop out instantly; tours the
  // search no longer returns (inactive/removed) are simply absent from the pool.
  const tours = useMemo(
    () => items.map((i) => pool[String(i.id)]).filter(Boolean),
    [items, pool]
  );

  // Fetch only the ids we don't already hold, and merge them into the pool.
  useEffect(() => {
    if (!hydrated) return;
    if (count === 0) {
      setToursLoading(false);
      return;
    }
    const missing = items
      .map((i) => i.id)
      .filter((id) => !(String(id) in pool));
    if (missing.length === 0) {
      setToursLoading(false);
      return;
    }
    setToursLoading(true);
    getWishlistTours(missing)
      .then((res) => {
        const fetched: Record<string, any> = {};
        for (const t of res.tours ?? []) fetched[String(t.id)] = t;
        setPool((prev) => ({ ...prev, ...fetched }));
        setToursLoading(false);
      })
      .catch(() => setToursLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsKey, hydrated]);

  // Fetch prices once the tours are in, mirroring the category page's TourList.
  useEffect(() => {
    if (tours.length === 0) {
      setPrices([]);
      setPriceLoading(false);
      return;
    }
    setPriceLoading(true);
    getTourPricing(
      tours.map((t) => t.id),
      getCookie("currency")
    ).then((res) => {
      setPrices(
        res.map((item: any) => ({
          tourId: item.id,
          price: item.price,
          oldPrice: item.old_price,
          paxLeft: item.promotionDetail?.pax_left ?? 0,
          currency: item.currency,
        }))
      );
      setPriceLoading(false);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tours]);

  return (
    <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-py-8 min-[721px]:tw-py-12">
      <div className="tw-flex tw-items-center tw-gap-3 tw-mb-1">
        <h1 className="tw-text-[26px] min-[721px]:tw-text-[32px] tw-font-extrabold tw-text-[#14101c] tw-m-0">
          My Wishlist
        </h1>
        {hydrated && count > 0 && (
          <span
            className="tw-inline-grid tw-place-items-center tw-text-white tw-font-bold tw-px-2 tw-h-7 tw-rounded-full tw-text-[14px]"
            style={{ background: "#854ec9", minWidth: 28 }}
          >
            {count}
          </span>
        )}
      </div>
      <p className="tw-text-[#5d556c] tw-text-[15px] tw-mb-7">
        Tours you&apos;ve saved. Your wishlist is stored on this device.
      </p>

      {/* Loading skeleton until localStorage is read and tours are fetched */}
      {(!hydrated || (count > 0 && toursLoading)) && (
        <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 xl:tw-grid-cols-4 tw-gap-4">
          {[...Array(8)].map((_, i) => (
            <ListingCardSkeleton key={i} />
          ))}
        </div>
      )}

      {/* Empty state */}
      {hydrated && count === 0 && (
        <div className="tw-flex tw-flex-col tw-items-center tw-justify-center tw-text-center tw-py-16">
          <div
            className="tw-w-20 tw-h-20 tw-rounded-full tw-grid tw-place-items-center tw-mb-5"
            style={{ background: "#f7eefc" }}
          >
            <svg
              width="38"
              height="38"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#854ec9"
              strokeWidth={1.8}
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden="true"
            >
              <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
            </svg>
          </div>
          <h2 className="tw-text-[20px] tw-font-bold tw-text-[#14101c] tw-mb-2">
            No saved tours yet
          </h2>
          <p className="tw-text-[#5d556c] tw-text-[15px] tw-mb-6 tw-max-w-[420px]">
            Tap the heart on any tour to save it here for later.
          </p>
          <a
            href="/"
            className="tw-inline-flex tw-items-center tw-gap-2 tw-px-5 tw-py-3 tw-rounded-full tw-text-white tw-font-semibold tw-text-[15px] tw-no-underline tw-transition-colors"
            style={{ background: "#854ec9" }}
          >
            Explore tours <span aria-hidden="true">→</span>
          </a>
        </div>
      )}

      {/* Wishlist grid — same standard tour card as the category pages */}
      {hydrated && count > 0 && !toursLoading && tours.length > 0 && (
        <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 xl:tw-grid-cols-4 tw-gap-4">
          {tours.map((tour: any, index: number) => (
            <ListingCard
              key={tour.id}
              detail={tour}
              priceLoading={priceLoading}
              priceInfo={prices.find((x: any) => x.tourId === tour.id)}
              priority={index < 4}
            />
          ))}
        </div>
      )}

      {/* Saved ids exist but none are currently bookable (inactive/removed). */}
      {hydrated && count > 0 && !toursLoading && tours.length === 0 && (
        <p className="tw-text-[#5d556c] tw-text-[15px] tw-py-8">
          Your saved tours aren&apos;t available right now. Please check back
          later.
        </p>
      )}
    </div>
  );
}
